    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nOrientation and reactivity in electrophilic aromatic substitution.\n\n2. GIVEN:\nSubstituted benzenes.\n\n3. FORMULA / PRINCIPLE:\nElectron-withdrawing groups with multiple bonds to electronegative atoms (-NO2, -CHO, -COOH, -CN) are meta-directing deactivators.\n\n4. STEP-BY-STEP SOLUTION:\n1. The nitro group (-NO2) withdraws electron density from the benzene ring through strong -M resonance and -I inductive effects.\n2. Resonance structures show that positive charges develop specifically at the ortho and para positions.\n3. Therefore, the meta positions are relatively less deactivated than ortho/para positions, directing the incoming electrophile to the meta position.\n4. -OH, -NH2, and -CH3 donate electrons, activating the ring and directing ortho/para.\n\n5. FINAL ANSWER:\nOption A: -NO2 (nitro group)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nGroups with lone pairs (-OH, -NH2) donate by +M effect and direct ortho/para.",
