      "given": "Substituted benzenes.",
      "formula": "Electron-withdrawing groups with multiple bonds to electronegative atoms (-NO2, -CHO, -COOH, -CN) are meta-directing deactivators.",
      "stepByStep": "1. The nitro group (-NO2) withdraws electron density from the benzene ring through strong -M resonance and -I inductive effects.\n2. Resonance structures show that positive charges develop specifically at the ortho and para positions.\n3. Therefore, the meta positions are relatively less deactivated than ortho/para positions, directing the incoming electrophile to the meta position.\n4. -OH, -NH2, and -CH3 donate electrons, activating the ring and directing ortho/para.",
