    "explanation": "1. CONCEPT:\nLimitations of Friedel-Crafts alkylation and acylation.\n\n2. GIVEN:\nAniline with Lewis acid AlCl3.\n\n3. FORMULA / PRINCIPLE:\nThe lone pair on the amino nitrogen coordinates strongly with the Lewis acid catalyst AlCl3, forming an adduct that deactivates the ring.\n\n4. STEP-BY-STEP SOLUTION:\n1. Aniline possesses a basic amino group (-NH2) with an unshared lone pair on nitrogen.\n2. When mixed with anhydrous AlCl3, it undergoes a Lewis acid-base complexation: C6H5NH2 + AlCl3 -> C6H5NH2+-AlCl3-.\n3. This places a formal positive charge on the nitrogen atom attached directly to the ring.\n4. The resulting -NH2+-AlCl3- group exerts an overwhelming -I and -M deactivating effect, preventing electrophilic attack by carbocations.\n\n5. FINAL ANSWER:\nOption A: Aniline (C6H5NH2)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nStrongly basic amino groups complex with AlCl3 and strongly deactivating groups (-NO2) fail to undergo Friedel-Crafts reaction.",
    "solutionStructured": {
      "concept": "Limitations of Friedel-Crafts alkylation and acylation.",
      "given": "Aniline with Lewis acid AlCl3.",
      "formula": "The lone pair on the amino nitrogen coordinates strongly with the Lewis acid catalyst AlCl3, forming an adduct that deactivates the ring.",
      "stepByStep": "1. Aniline possesses a basic amino group (-NH2) with an unshared lone pair on nitrogen.\n2. When mixed with anhydrous AlCl3, it undergoes a Lewis acid-base complexation: C6H5NH2 + AlCl3 -> C6H5NH2+-AlCl3-.\n3. This places a formal positive charge on the nitrogen atom attached directly to the ring.\n4. The resulting -NH2+-AlCl3- group exerts an overwhelming -I and -M deactivating effect, preventing electrophilic attack by carbocations.",
      "finalAnswer": "Option A: Aniline (C6H5NH2)",
      "whyOtherOptionsWrong": "Strongly basic amino groups complex with AlCl3 and strongly deactivating groups (-NO2) fail to undergo Friedel-Crafts reaction."
    },
