    "explanation": "1. CONCEPT:\nBonding and geometry in alkenes.\n\n2. GIVEN:\nEthene H2C=CH2.\n\n3. FORMULA / PRINCIPLE:\nsp2 hybridization gives trigonal planar geometry with ~120\u00b0 bond angles.\n\n4. STEP-BY-STEP SOLUTION:\n1. In ethene, both carbon atoms are sp2 hybridized, having three equivalent sp2 hybrid orbitals in a plane oriented at 120\u00b0 to one another.\n2. Each carbon forms three sigma bonds (two C-H and one C-C) and one pi bond formed by lateral overlap of unhybridized 2p orbitals.\n3. VSEPR theory dictates that three electron domains adopt a trigonal planar geometry with H-C-H and H-C-C bond angles close to 117.6\u00b0 and 121.2\u00b0 (approximately 120\u00b0).\n\n5. FINAL ANSWER:\nOption A: Trigonal planar, approximately 120\u00b0\n\n6. WHY OTHER OPTIONS ARE WRONG:\nTetrahedral geometry (109.5\u00b0) occurs in sp3 alkanes; linear geometry (180\u00b0) occurs in sp alkynes.",
