    "explanation": "1. CONCEPT:\nBaeyer's test for unsaturation (alkenes and alkynes).\n\n2. GIVEN:\nCold dilute alkaline KMnO4 (1%).\n\n3. FORMULA / PRINCIPLE:\nSyn-dihydroxylation of C=C to form vicinal diols with discharge of purple colour.\n\n4. STEP-BY-STEP SOLUTION:\n1. Baeyer's reagent is a 1% cold, alkaline aqueous solution of potassium permanganate (KMnO4).\n2. When shaken with an alkene or alkyne, it oxidizes the multiple bond by syn-addition of two -OH groups to yield a vicinal glycol.\n3. In doing so, the deep purple colour of MnO4- is decolourized with the formation of a brown precipitate of MnO2: R-CH=CH2 + [O] + H2O -> R-CH(OH)-CH2OH.\n4. This decolourization confirms the presence of aliphatic unsaturation.\n\n5. FINAL ANSWER:\nOption A: Cold dilute alkaline potassium permanganate (KMnO4) solution\n\n6. WHY OTHER OPTIONS ARE WRONG:\nAcidified KMnO4 causes destructive cleavage; Baeyer's reagent is strictly cold, dilute, and alkaline.",
