    "question": "Benzene reacts with chlorine in the presence of anhydrous AlCl3 in the dark to produce chlorobenzene. Here, the catalyst anhydrous AlCl3 acts as a:",
    "options": {
      "A": "Lewis acid to generate the chloronium electrophile (Cl+)",
      "B": "Bronsted base to remove protons",
      "C": "Reducing agent to donate electrons",
      "D": "Free radical initiator"
    },
    "optionsList": [
      "Lewis acid to generate the chloronium electrophile (Cl+)",
      "Bronsted base to remove protons",
      "Reducing agent to donate electrons",
      "Free radical initiator"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nRole of Lewis acid catalyst in electrophilic aromatic halogenation.\n\n2. GIVEN:\nCl2 + AlCl3 <=> Cl+...AlCl4-.\n\n3. FORMULA / PRINCIPLE:\nAlCl3 polarizes Cl-Cl bond to release chloronium ion.\n\n4. STEP-BY-STEP SOLUTION:\n1. Anhydrous aluminium chloride (AlCl3) is an electron-deficient compound with a vacant 3p orbital on Al.\n2. It acts as a Lewis acid and coordinates with one chlorine atom of Cl2, weakening the Cl-Cl bond: Cl-Cl + AlCl3 -> [Cl...Cl...AlCl3] -> Cl+ + [AlCl4]-.\n3. This generates the powerful electrophile (Cl+ or polarized Cl-Cl complex) capable of attacking the aromatic pi cloud.\n\n5. FINAL ANSWER:\nOption A: Lewis acid to generate the chloronium electrophile (Cl+)\n\n6. WHY OTHER OPTIONS ARE WRONG:\nAlCl3 is an electron-pair acceptor (Lewis acid), not a Bronsted base or free radical generator.",
    "solutionStructured": {
      "concept": "Role of Lewis acid catalyst in electrophilic aromatic halogenation.",
      "given": "Cl2 + AlCl3 <=> Cl+...AlCl4-.",
      "formula": "AlCl3 polarizes Cl-Cl bond to release chloronium ion.",
      "stepByStep": "1. Anhydrous aluminium chloride (AlCl3) is an electron-deficient compound with a vacant 3p orbital on Al.\n2. It acts as a Lewis acid and coordinates with one chlorine atom of Cl2, weakening the Cl-Cl bond: Cl-Cl + AlCl3 -> [Cl...Cl...AlCl3] -> Cl+ + [AlCl4]-.\n3. This generates the powerful electrophile (Cl+ or polarized Cl-Cl complex) capable of attacking the aromatic pi cloud.",
      "finalAnswer": "Option A: Lewis acid to generate the chloronium electrophile (Cl+)",
      "whyOtherOptionsWrong": "AlCl3 is an electron-pair acceptor (Lewis acid), not a Bronsted base or free radical generator."
    },
