      "given": "Ethene H2C=CH2.",
      "formula": "sp2 hybridization gives trigonal planar geometry with ~120\u00b0 bond angles.",
      "stepByStep": "1. In ethene, both carbon atoms are sp2 hybridized, having three equivalent sp2 hybrid orbitals in a plane oriented at 120\u00b0 to one another.\n2. Each carbon forms three sigma bonds (two C-H and one C-C) and one pi bond formed by lateral overlap of unhybridized 2p orbitals.\n3. VSEPR theory dictates that three electron domains adopt a trigonal planar geometry with H-C-H and H-C-C bond angles close to 117.6\u00b0 and 121.2\u00b0 (approximately 120\u00b0).",
      "finalAnswer": "Option A: Trigonal planar, approximately 120\u00b0",
